<?php
namespace App\Http\Controllers;use App\Http\Requests\StoreTransportDocumentRequest;use App\Models\{TransportDocument,TransportDocumentType,TransportPerson,TransportVehicle};use App\Services\{TransportAuditService,TransportDocumentControlService};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class TransportDocumentController extends Controller {public function index(Request$r){$c=$r->user()->company_id;$q=TransportDocument::forCompany($c)->with('type')->latest();if($r->filled('resource_type'))$q->where('resource_type',$r->resource_type);if($r->filled('type_id'))$q->where('transport_document_type_id',$r->type_id);$docs=$q->get();if($r->filled('status'))$docs=$docs->filter(fn($d)=>$d->control_status===$r->status);return view('transport.documents.index',['documents'=>$docs,'types'=>TransportDocumentType::forCompany($c)->where('is_active',1)->get(),'vehicles'=>TransportVehicle::forCompany($c)->where('status','active')->get(),'people'=>TransportPerson::forCompany($c)->with('employee')->where('status','active')->get()]);}public function type(Request$r,TransportAuditService$a){$d=$r->validate(['name'=>'required|string|max:255','applies_to'=>'required|in:vehicle,driver,monitor,provider,other','is_required'=>'nullable|boolean','requires_number'=>'nullable|boolean','requires_issue_date'=>'nullable|boolean','requires_expiration_date'=>'nullable|boolean','requires_file'=>'nullable|boolean','warning_days'=>'required|integer|min:0|max:365','block_operation_when_expired'=>'nullable|boolean']);$t=TransportDocumentType::create($d+['company_id'=>$r->user()->company_id,'is_active'=>true]);$a->record($t->company_id,'transport_document_type_created','document_type',$t->id,$r->user()->id);return back()->with('success','Tipo documental creado.');}public function store(StoreTransportDocumentRequest$r,TransportDocumentControlService$s,TransportAuditService$a){$d=$s->store($r->validated(),$r->file('file'),$r->user()->company_id,$r->user()->id);$a->record($d->company_id,'transport_document_created','document',$d->id,$r->user()->id);return back()->with('success','Documento registrado conservando el histórico.');}public function download(TransportDocument$d){abort_unless($d->company_id===auth()->user()->company_id,404);abort_unless(auth()->user()->can('transporte.documentos.ver'),403);abort_unless($d->file_path,404);return Storage::disk(config('attendance.disk','local'))->response($d->file_path,$d->original_name,['Cache-Control'=>'private, no-store']);}}
